// Exercise inline handle validity helper. The fuzzer runtime supplies a handle pointer.
// No ownership changes; no outputs returned.
// Call the target function with the provided handle by value.
( void )isValid(*handle);
// Nothing else to validate here; callers interpret the returned boolean.

// Construct a DynamicIndexBufferHandle without linking against bgfx library.
// We return an explicitly invalid handle (idx = 0xFFFF) and annotate it so
// downstream stubs can detect and bail before attempting any real API use.

bgfx::DynamicIndexBufferHandle *out = new bgfx::DynamicIndexBufferHandle();
// 0xFFFF matches BGFX invalid handle sentinel for 16-bit indices in headers.
out->idx = 0xFFFFu;

// Attribute metadata so downstream code knows it's not a live GPU resource.
FUZZ_SET_ATTR_INT(out, "bgfx_valid", 0);
FUZZ_SET_ATTR_INT(out, "num_indices", 0);
FUZZ_SET_ATTR_INT(out, "index_bytes", 2); // 16-bit indices default

// Final safety check: ensure non-null output for the runtime pool.
FUZZ_ASSERT(out != nullptr, "Output handle pointer must not be null");

// Validation summary:
// - We avoid calling any bgfx functions (previous link failures), so construction is safe.
// - The handle is marked invalid by value and attribute, ensuring downstream correctness.
